});

test('createInvoice reports invalid quantity (zero)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid quantity (negative)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid quantity (non-integer string)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: '5' }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice reports unknown SKU even with valid first line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'UNKNOWN', qty: 1 },
    ],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const inputLines = [{ sku: 'ICON-SET', qty: 2 }];
  const original = JSON.parse(JSON.stringify(inputLines));
  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: inputLines,
  });
  assert.deepEqual(inputLines, original);
});

test('createInvoice returns a new lines array (not the original)', () => {
  const inputLines = [{ sku: 'ICON-SET', qty: 2 }];
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: inputLines,
  });
  assert.notEqual(r.value.lines, inputLines);
  assert.notEqual(r.value.lines[0], inputLines[0]);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = { qty: 2, unitPrice: 980 };
  assert.equal(lineTotal(line), 1960);
});

test('lineTotal handles qty of 1', () => {
  const line = { qty: 1, unitPrice: 8500 };
  assert.equal(lineTotal(line), 8500);
});

test('lineTotal handles large quantities', () => {
  const line = { qty: 100, unitPrice: 120000 };
  assert.equal(lineTotal(line), 12000000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 980 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1960);
  assert.equal(totals.total, 1960);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 980 },
      { qty: 1, unitPrice: 8500 },
      { qty: 3, unitPrice: 50 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1960 + 8500 + 150);
  assert.equal(totals.total, 1960 + 8500 + 150);
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns an object with both subtotal and total', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('total' in totals);
});
